import org.vaadin.addons.dramafinder.element.MultiSelectComboBoxElement;
import org.vaadin.addons.dramafinder.element.TextFieldElement;

@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
class TmpBrowserCheck extends AbstractBasePlaywrightIT {

    @LocalServerPort
    private int port;

    @Autowired
    private QueryLog queryLog;

    @Override
    public String getUrl() {
        return "http://localhost:" + port;
    }

    @Test
    void typingFiltersTheGridWithoutManyBackendQueriesAndUpdatesTheUrl() {
        TextFieldElement nameFilter = new TextFieldElement(page.locator("vaadin-text-field"));
        GridElement grid = GridElement.get(page);

        assertEquals(500, grid.getTotalRowCount());

        queryLog.clear();
        nameFilter.getInputLocator().pressSequentially("aaltonen",
                new Locator.PressSequentiallyOptions().setDelay(50));
        page.waitForTimeout(800);

        int filteredCount = grid.getTotalRowCount();
        System.out.println("TMP filteredCount=" + filteredCount);
        System.out.println("TMP countQueries=" + queryLog.countQueries());
        System.out.println("TMP pageQueries=" + queryLog.pageQueries());
        System.out.println("TMP url=" + page.url());

        assertTrue(filteredCount < 500 && filteredCount > 0);
        assertTrue(queryLog.countQueries().size() <= 2,
                "Typing a nine-letter name should cost one or two backend queries, was "
                        + queryLog.countQueries().size());
        assertTrue(page.url().contains("name=aaltonen"), "url was " + page.url());
    }

    @Test
    void selectingAStatusUpdatesTheUrlWithLiteralCommas() {
        MultiSelectComboBoxElement statusFilter = MultiSelectComboBoxElement.getByLabel(page, "Status");
        statusFilter.selectItems("CLOSED", "ACTIVE");
        page.waitForTimeout(300);

        System.out.println("TMP url2=" + page.url());
        assertTrue(page.url().contains("status=ACTIVE,CLOSED"), "url was " + page.url());
    }
}
