+    private static boolean containsRowWithText(Grid<?> grid, String text) {
+        for (int i = 0; i < _size(grid); i++) {
+            if (_getFormattedRow(grid, i).stream().anyMatch(cell -> cell.contains(text))) {
+                return true;
+            }
+        }
+        return false;
+    }
+
+    /** Finds the URL from the last {@code history.replaceState} call the view triggered. */
+    private static String lastReplaceStateUrl() {
+        List<PendingJavaScriptInvocation> invocations =
+                UI.getCurrent().getInternals().dumpPendingJavaScriptInvocations();
+        String url = null;
+        for (PendingJavaScriptInvocation invocation : invocations) {
+            JavaScriptInvocation js = invocation.getInvocation();
+            String expression = js.getExpression();
+            assertFalse(expression.contains("pushState"), "Filtering must not push a new history entry");
+            if (expression.contains("replaceState")) {
+                url = String.valueOf(js.getParameters().get(1));
+            }
+        }
+        assertNotNull(url, "Expected a history.replaceState call");
+        return url;
+    }
